function validate([workers, tasks]) {
  if (workers.length < 1 || workers.length > 100000) return 'workers needs 1 to 10^5 values.';
  if (workers.some(s => s < 1 || s > 1e9)) return 'Each skill level in workers is between 1 and 10^9.';
  if (tasks.length < 1 || tasks.length > 100000) return 'tasks needs 1 to 10^5 entries.';
  if (tasks.some(task => task.length !== 2)) return 'Each task is a pair [skill, profit].';
  if (tasks.some(([skill, profit]) => skill < 1 || skill > 1e9 || profit < 1 || profit > 1e9)) return 'Task skills and profits are between 1 and 10^9.';
  return null;
}

