function maxProfit(workers, tasks) {
  const workerCount = new Map();
  for (const skill of workers) {
    workerCount.set(skill, (workerCount.get(skill) ?? 0) + 1);
  }
  const bySkill = new Map();
  for (const [skill, profit] of tasks) {
    if (!bySkill.has(skill)) bySkill.set(skill, []);
    bySkill.get(skill).push(profit);
  }

  let total = 0;
  let extra = 0;
  for (const [skill, profits] of bySkill) {
    profits.sort((a, b) => b - a);
    const matched = Math.min(workerCount.get(skill) ?? 0, profits.length);
    for (let i = 0; i < matched; i++) {
      total += profits[i];
    }
    if (matched < profits.length) {
      extra = Math.max(extra, profits[matched]);
    }
  }
  return total + extra;
}

