function maxProfit(workers, tasks) {
  // Decide every task in turn: leave it, give it to the additional worker, or give it to a free worker of equal skill.
  const used = new Array(workers.length).fill(false);
  const search = (index, additionalFree) => {
    if (index === tasks.length) return 0;
    const [skill, profit] = tasks[index];
    let best = search(index + 1, additionalFree);
    if (additionalFree) best = Math.max(best, profit + search(index + 1, false));
    for (let w = 0; w < workers.length; w++) {
      if (used[w] || workers[w] !== skill) continue;
      used[w] = true;
      best = Math.max(best, profit + search(index + 1, additionalFree));
      used[w] = false;
    }
    return best;
  };
  return search(0, true);
}

