function generate(rand, size) {
  const large = size === 'large';
  const workerTotal = large ? 2000 : 1 + Math.floor(rand() * 5);
  const taskTotal = large ? 2000 : 1 + Math.floor(rand() * 6);
  // Few skill levels make matches common; now and then a skill comes from the whole range and matches nothing.
  const levels = large ? 300 + Math.floor(rand() * 1200) : 1 + Math.floor(rand() * 4);
  const skill = () => (rand() < 0.1 ? 1 + Math.floor(rand() * 1e9) : 1 + Math.floor(rand() * levels));
  const top = large || rand() < 0.3 ? 1e9 : 10;
  const workers = Array.from({ length: workerTotal }, () => skill());
  const tasks = Array.from({ length: taskTotal }, () => [skill(), 1 + Math.floor(rand() * top)]);
  return [workers, tasks];
}
